namespace CheckoutPricing.Domain;

public static class LoyaltyDiscountPolicy
{
    private const int MinimumSubtotalCents = 3_000;
    private const int CapCents = 2_000;

    public static int Compute(int subtotalCents, LoyaltyTier tier)
    {
        if (subtotalCents < MinimumSubtotalCents)
            return 0;
        return Math.Min(subtotalCents * PercentOf(tier) / 100, CapCents);
    }

    private static int PercentOf(LoyaltyTier tier) => tier switch
    {
        LoyaltyTier.Bronze => 5,
        LoyaltyTier.Silver => 10,
        LoyaltyTier.Gold => 15,
        LoyaltyTier.Platinum => 20,
        _ => 0
    };
}
E
cat > $D/PromoCodePolicy.cs <<'E'
namespace CheckoutPricing.Domain;

public static class PromoCodePolicy
{
    private const int WelcomeFiveCents = 500;
    private const int SummerTenCapCents = 1_500;

    public static int Compute(string? code, int remainingCents)
    {
        if (string.Equals(code, "WELCOME5", StringComparison.OrdinalIgnoreCase))
            return WelcomeFiveCents;
        if (string.Equals(code, "SUMMER10", StringComparison.OrdinalIgnoreCase))
            return Math.Min(remainingCents / 10, SummerTenCapCents);
        return 0;
    }
}
E
