namespace CheckoutPricing.Domain;

public static class DiscountPolicy
{
    public static int Compute(int subtotalCents, LoyaltyTier tier, string? promoCode)
    {
        var loyaltyCents = LoyaltyDiscountPolicy.Compute(subtotalCents, tier);
        var promoCents = PromoCodePolicy.Compute(promoCode, subtotalCents - loyaltyCents);
        return Math.Min(loyaltyCents + promoCents, subtotalCents);
    }
}
